{"doneWhen":{"all":[{"path":"countObjects(kind=item, name=Crown)","op":">=","value":1}]},"modes":[{"id":"collect-and-craft","priority":10,"when":{"all":[{"path":"body.x","op":">=","value":0}]},"macro":"skill","params":{"name":"field-work"}}],"skills":[{"name":"field-work","skill":"async (b) => {
  const need = { Wood: 3, Stone: 2 };
  const have = { Wood: 0, Stone: 0 };
  const items = await b.items();
  for (const it of items) {
    if (it.name === 'Wood') have.Wood += it.stack;
    if (it.name === 'Stone') have.Stone += it.stack;
  }
  b.log('start have ' + JSON.stringify(have));

  // Pick up keys first (red key opens red door, blue key opens blue door)
  const keys = [
    { name: 'Red Key', x: 2, y: 2 },
    { name: 'Blue Key', x: 11, y: 1 }
  ];
  for (const k of keys) {
    const r = await b.walkTo(k.x, k.y, 'adjacent');
    if (!r.ok) { b.log('walk fail ' + k.name + ' ' + r.reason); continue; }
    const p = await b.faceAndPress(k.x, k.y, 'KeyE');
    b.log('pick ' + k.name + ' ' + JSON.stringify(p));
  }

  // Collect materials. Wood at (10,3) and (10,1) are reachable directly.
  // Stone at (10,7) and (11,8) may be behind the blue door; try direct first.
  const targets = [
    { name: 'Wood', x: 10, y: 3 },
    { name: 'Wood', x: 10, y: 1 },
    { name: 'Stone', x: 10, y: 7 },
    { name: 'Stone', x: 11, y: 8 }
  ];
  for (const t of targets) {
    if (have[t.name] >= need[t.name]) continue;
    let r = await b.walkTo(t.x, t.y, 'adjacent');
    if (!r.ok) {
      b.log('walk fail ' + t.name + ' ' + r.reason + ', trying door unlock');
      // Try unlocking blue door at (8,6) then red door at (8,3)
      const doors = [ {x:8,y:6}, {x:8,y:3} ];
      for (const d of doors) {
        const dr = await b.walkTo(d.x, d.y, 'adjacent');
        if (dr.ok) {
          const dp = await b.faceAndPress(d.x, d.y, 'KeyE');
          b.log('unlock door ' + JSON.stringify(d) + ' ' + JSON.stringify(dp));
        }
      }
      r = await b.walkTo(t.x, t.y, 'adjacent');
    }
    if (!r.ok) { b.log('walk fail ' + t.name + ' ' + r.reason); continue; }
    const p = await b.faceAndPress(t.x, t.y, 'KeyE');
    b.log('pick ' + t.name + ' ' + JSON.stringify(p));
    if (p && p.ok) have[t.name]++;
  }

  if (have.Wood < 3 || have.Stone < 2) {
    b.log('missing materials ' + JSON.stringify(have));
    return;
  }
  const w = await b.walkTo(6, 2, 'adjacent');
  if (!w.ok) { b.log('bench walk fail ' + w.reason); return; }
  const c = await b.faceAndPress(6, 2, 'KeyC');
  b.log('craft ' + JSON.stringify(c));
}","check":"async (b) => {
  const items = await b.items();
  const crown = items.find(i => i.name === 'Crown');
  return { ok: !!crown, detail: crown ? 'Crown crafted' : 'no Crown yet' };
}"}]}
